"""Explain local and sync instrumentation names, generic counts and fallback priority."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1597': ('명찰 끝에 특별한 표시가 있으면 다른 안내를 붙이는 규칙을 생각해 봅시다. 생성기는 이름 끝의 _local과 순서 꼬리표를 따로 확인해요.', 'local·sync 이름과 순서 표식 선택 규칙을 구별합니다.', 'try_cmpxchg_local → 표식 없음, sync_cmpxchg → kcsan_mb, cmpxchg_release → kcsan_release를 적으세요. 여기서 표식 없음은 접근 보고도 없다는 뜻이 아니에요.', ['gen_xchg는 먼저 kcsan_barrier를 빈 문자열로 시작해요. 여기에 KCSAN 분석용 순서 표식을 넣을지 고를 거예요. KCSAN은 동시에 같은 자료에 접근하는 문제를 살펴보는 기능이에요.', '${xchg%_local}은 이름 끝의 _local을 떼어 보는 쉘 표현이에요. 떼기 전후 이름이 같으면 원래 _local로 끝나지 않았다는 뜻이에요. 이 경우에만 다음 순서 이름 검사를 해요.', '그 안에서 order가 _release이면 kcsan_release, 빈 값이면 kcsan_mb를 골라요. _acquire와 _relaxed에는 이 분기에서 고르는 표식이 없어요. 이름 끝 검사와 order 검사는 별개의 조건이에요.', 'try_cmpxchg_local은 _local로 끝나므로 바깥 조건을 통과하지 않아요. 그래서 이 생성기는 kcsan_mb를 앞에 넣지 않아요. 하지만 대상과 예상 메모의 접근 hook은 여전히 생성돼요.', 'sync_cmpxchg는 _local로 끝나지 않고 여기서 order가 비어 있으므로 kcsan_mb를 골라요. sync가 붙었다는 이유로 특별한 생략 규칙이 있다고 추측하면 안 돼요. 실제 조건식을 따라 읽으세요.', '이 표는 계측 표식의 생성 규칙이에요. 실제 CPU의 원자성·순서·지원 조건은 해당 raw 구현의 약속도 봐야 해요. 특히 local이라는 이름만 보고 다른 CPU와의 동기화에 일반형처럼 써도 된다고 판단하면 안 돼요.'], [('try_cmpxchg_local 앞에 이 생성기가 kcsan_mb를 넣나요?', ['네. 기본 순서 이름이면 예외 없이 넣어요', '아니요. _local로 끝나는 이름은 이 표식 선택에서 빠져요'], '정답은 두 번째예요. 바깥 조건이 먼저 _local 여부를 검사해요. order가 비었다는 조건만 보면 이름 끝의 예외를 놓쳐요.'), ('sync_cmpxchg의 기본 생성 표식은 무엇인가요?', ['kcsan_mb예요', 'sync라는 이름 때문에 언제나 아무 표식도 없어요'], '정답은 첫 번째예요. _local로 끝나지 않아 순서 검사를 하고, 빈 order가 mb를 고르게 해요. 접근 보고와 분석용 순서 표식을 구별하세요.')]), 'os1598': ('이름 안에 “시도”라는 말이 들어 있는지와 이름이 “시도”로 시작하는지는 다른 조건이에요. 생성기는 그 차이에 따라 예상 메모의 보고를 다르게 만들어요.', '이름의 시작 부분 검사와 실제 예상 값 갱신을 구별합니다.', 'try_cmpxchg → 예상 포인터를 따로 저장·보고, sync_try_cmpxchg → ptr와 나머지 인자 전달의 두 갈래를 그리세요.', ['gen_xchg는 이름이 try_cmpxchg로 시작하는지 검사해요. 단순히 이름 어딘가에 그 글자가 들어 있으면 통과하는 검사가 아니에요. 앞부분을 확인하는 조건이에요.', 'try_cmpxchg나 try_cmpxchg64는 그 앞부분으로 시작해요. 이 갈래는 oldp를 __ai_oldp에 따로 담고 예상 메모의 instrument_read_write 보고를 만들어요.', 'sync_try_cmpxchg는 맨 앞이 sync_이므로 그 갈래로 들어가지 않아요. 대신 ptr와 나머지 인자를 받는 형태로 생성돼요. 나머지 인자는 __VA_ARGS__라는 가변 인자 표기로 raw 함수에 전달해요.', '실제 생성 매크로에는 __ai_ptr, kcsan_mb, 대상의 instrument_atomic_read_write, raw_sync_try_cmpxchg 호출이 있어요. 별도의 __ai_oldp 변수나 예상 메모 hook은 이 매크로에 없어요.', '그래도 raw에 전달되는 예상 포인터가 사라지는 것은 아니에요. 나머지 인자로 전달돼 raw의 비교 실패 계약에 따라 예상 메모가 관찰한 값으로 바뀔 수 있어요. 보고가 없는 것과 실제 쓰기가 없는 것은 달라요.', '이 차이 하나로 모든 KCSAN 탐지가 잘못됐다고 단정할 수는 없어요. 여기서는 생성 분기와 해당 매크로에서 보이는 보고의 차이를 확인해요. 전체 분석 기능의 결과는 별도의 실제 검사가 필요해요.'], [('이 생성 결과의 sync_try_cmpxchg에는 예상 메모만을 위한 별도 hook이 있나요?', ['네. 이름 안에 try가 있으면 모두 같은 분기로 가요', '아니요. 이 매크로에는 대상 hook과 mb 표식이 있어요'], '정답은 두 번째예요. 검사하는 것은 try_cmpxchg로 시작하는지예요. sync_가 먼저 붙으면 예상 메모를 따로 처리하는 분기로 가지 않아요.'), ('별도 예상 메모 hook이 없으면 실패 때 예상 값도 절대 바뀌지 않나요?', ['아니요. raw가 받는 인자와 실제 갱신 계약은 별개예요', '네. 보고가 없으면 변수의 값도 바뀔 수 없어요'], '정답은 첫 번째예요. 예상 포인터는 나머지 인자에 들어 raw로 전달될 수 있어요. 분석 보고와 실제 연산 동작을 따로 확인하세요.')]), 'os1599': ('일곱 종류에 선택 사항 네 개씩 붙이고, 별도 종류 여덟 개를 더하면 몇 개일까요? 생성 목록을 세는 계산과 실제 실행 검사는 다른 일이에요.', 'generic 매크로의 개수를 세고 생성·컴파일·실행의 범위를 구별합니다.', '일반 계열 7×4=28, local·sync 8개를 더해 36개라고 적으세요. typed wrapper 255개는 별도 칸에 두세요.', ['생성기는 xchg, cmpxchg, cmpxchg64, cmpxchg128, try_cmpxchg, try_cmpxchg64, try_cmpxchg128의 일곱 이름을 순회해요. 64·128은 관련 연산의 값 폭을 구별하는 이름이에요.', '각 이름마다 기본·_acquire·_release·_relaxed의 네 형태를 만들어요. 그래서 첫 목록은 7×4=28개예요. 이름이 많아도 실제 호출 때 모두 실행하는 것은 아니에요.', '다음 목록에서는 local·sync 여덟 종류를 각각 한 번씩 만들어요. 이를 더하면 generic 매크로는 28+8=36개예요. 앞서 센 자료형별 함수 255개와 같은 종류의 목록이 아니므로 따로 구별해요.', '매크로는 C 코드의 모양을 펼치는 규칙이에요. 헤더에 정의가 존재한다고 모든 매크로가 실제 호출 지점에서 펼쳐져 컴파일됐다는 뜻은 아니에요. 사용한 정의와 쓰지 않은 정의를 나누어 봐야 해요.', '헤더를 다시 생성해 글자가 같다고 확인하는 일, 코드를 컴파일하는 일, 특정 입력으로 실행하는 일은 다른 검사예요. 특히 128비트 이름이 생성됐다는 이유만으로 그 기계에서 해당 연산을 실제 실행했다고 말할 수 없어요.', '실제로 사용할 때는 해당 CPU와 구현이 그 폭의 API를 지원하는지 확인해요. 검사 결과도 생성한 목록, 컴파일한 경로, 실행한 사례를 따로 기록해야 해요. 한 가지 성공을 모든 아키텍처의 실행 보장으로 확대하지 마세요.'], [('이 생성기의 generic 매크로 수는 몇 개인가요?', ['typed wrapper 수와 같아 항상 255개예요', '7×4+8로 36개예요'], '정답은 두 번째예요. 네 순서 형태를 만드는 일곱 이름과 local·sync 여덟 이름을 더해요. 자료형별 함수 수와 generic 매크로 수는 별도예요.'), ('헤더 전체 재생성 결과가 같으면 실제 128비트 backend를 실행한 증거인가요?', ['아니요. 어떤 매크로와 구현을 실제 호출했는지 별도로 확인해야 해요', '네. 코드를 생성하면 모든 CPU 명령도 실행돼요'], '정답은 첫 번째예요. 글자를 만드는 단계와 하드웨어에서 실행하는 단계는 달라요. 생성 파일 일치만으로 128비트 실행이나 모든 CPU 지원을 주장할 수 없어요.')]), 'os1600': ('필요한 전용 도구가 있으면 바로 쓰고, 없으면 이미 가진 도구들을 올바르게 조합할 수 있어요. fallback은 이런 대체 구현을 선택하는 방법이에요.', '직접 제공된 arch 연산과 대체 구현의 우선순위를 이해합니다.', '필요한 raw API → 같은 arch API 있음? → 직접 호출 / 없으면 지원되는 조합과 템플릿 확인의 흐름을 그리세요.', ['아키텍처는 CPU 계열의 구조와 규칙을 말해요. arch_ 이름의 원자 함수는 그 계열이 제공하는 기반 연산과 연결돼요. primitive는 다른 기능을 만드는 바탕이 되는 연산이라는 뜻이에요.', 'fallback 생성기는 이 기반 연산과 양식을 이용해 raw 원자 API를 만들어요. 필요한 API가 직접 제공되면 그것을 쓰고, 없을 때 지원되는 다른 연산 조합으로 같은 약속을 마련하려는 설계예요.', '생성되는 선택문에서는 같은 이름과 순서의 arch 함수가 정의돼 있으면 먼저 직접 호출해요. 대체 코드가 있다는 이유로 항상 비교 교체 반복문부터 실행하는 것은 아니에요.', '직접 형태가 없으면 지원된 relaxed 연산에 순서 장벽을 더하거나, 더 강한 기본 연산을 이용하거나, 해당 연산의 템플릿을 쓰는 후보를 검토해요. 모든 연산에 같은 대체법이 있는 것은 아니며 가능한 경로가 없으면 오류가 나거나 필수 arch 제공이 필요해요.', '선택문 #if defined와 #elif는 C 전처리 지시문이에요. 생성된 C를 커널 설정과 arch 정의에 맞춰 컴파일할 때 경로를 고르는 데 써요. 매 원자 호출마다 쉘이 모든 CPU를 찾아보는 방식이 아니에요.', 'fallback이라고 원자성을 포기한 보통 읽기·쓰기라는 뜻은 아니에요. 대체 구현도 필요한 원자성과 순서 약속을 지켜야 해요. 어떤 기반 연산을 쓰고 어떤 보호를 덧붙이는지 실제 선택된 경로를 읽는 것이 중요해요.'], [('필요한 이름과 순서의 arch API가 제공되면 어떤 경로를 우선 쓰나요?', ['항상 비교 교체 반복문부터 실행해요', '해당 arch API를 직접 호출해요'], '정답은 두 번째예요. 생성 분기의 첫 #if defined가 그 제공 여부를 확인해요. 직접 도구가 있을 때와 조합해 만드는 대체 경로를 구별하세요.'), ('생성된 fallback 코드에서 설정과 arch 정의에 따른 경로는 언제 선택되나요?', ['C를 컴파일하는 과정에서 선택돼요', '매 호출마다 쉘이 모든 아키텍처를 검색해요'], '정답은 첫 번째예요. 생성기가 출력한 것은 C 전처리 조건이에요. 코드 생성, 컴파일 때 선택, 실제 원자 호출은 각각 다른 단계예요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_395.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
